+        serde_json::json!({"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"add_operation","arguments":{"kind":"Face","tool":"EM-0400-2FL"}}}),
+        serde_json::json!({"jsonrpc":"2.0","id":4,"method":"tools/call","params":{"name":"generate","arguments":{}}}),
